"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[5640],{780(e,n,t){t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>a,default:()=>p,frontMatter:()=>o,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"workshops/distributed-training-beginner/ddp-script","title":"Anatomy of a DDP Training Script","description":"We\'ll build a DDP pre-training script step by step, evolving from a single-GPU baseline to a full multi-node script using Qwen-2.5-0.5B as the model.","source":"@site/docs/03-workshops/01-distributed-training-beginner/02-ddp-script.mdx","sourceDirName":"03-workshops/01-distributed-training-beginner","slug":"/workshops/distributed-training-beginner/ddp-script","permalink":"/ai-on-sagemaker-hyperpod/docs/workshops/distributed-training-beginner/ddp-script","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":2,"frontMatter":{"title":"Anatomy of a DDP Training Script","sidebar_position":2},"sidebar":"tutorialSidebar","previous":{"title":"Understanding DataLoaders in DDP","permalink":"/ai-on-sagemaker-hyperpod/docs/workshops/distributed-training-beginner/dataloaders"},"next":{"title":"Running on SageMaker HyperPod with Slurm","permalink":"/ai-on-sagemaker-hyperpod/docs/workshops/distributed-training-beginner/slurm"}}');var s=t(4848),r=t(8453);const o={title:"Anatomy of a DDP Training Script",sidebar_position:2},a="Anatomy of a DDP Training Script",l={},d=[{value:"Step 1: Single-GPU Baseline",id:"step-1-single-gpu-baseline",level:2},{value:"Step 2: Initialize the Process Group",id:"step-2-initialize-the-process-group",level:2},{value:"Step 3: Wrap the Model with DDP",id:"step-3-wrap-the-model-with-ddp",level:2},{value:"Step 4: Use DistributedSampler for Data",id:"step-4-use-distributedsampler-for-data",level:2},{value:"Learning Rate Scaling",id:"learning-rate-scaling",level:2},{value:"Step 5: Full Working Script",id:"step-5-full-working-script",level:2}];function c(e){const n={blockquote:"blockquote",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",pre:"pre",strong:"strong",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"anatomy-of-a-ddp-training-script",children:"Anatomy of a DDP Training Script"})}),"\n",(0,s.jsxs)(n.p,{children:["We'll build a DDP pre-training script step by step, evolving from a single-GPU baseline to a full multi-node script using ",(0,s.jsx)(n.strong,{children:"Qwen-2.5-0.5B"})," as the model."]}),"\n",(0,s.jsx)(n.h2,{id:"step-1-single-gpu-baseline",children:"Step 1: Single-GPU Baseline"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-python",children:'import torch\nfrom transformers import AutoModelForCausalLM, AutoTokenizer\nfrom torch.utils.data import DataLoader, Dataset\n\nclass SimpleTextDataset(Dataset):\n    """Minimal dataset: pre-tokenized random sequences for demonstration."""\n    def __init__(self, tokenizer, num_samples=10000, seq_length=512):\n        self.input_ids = torch.randint(\n            0, tokenizer.vocab_size, (num_samples, seq_length)\n        )\n    \n    def __len__(self):\n        return len(self.input_ids)\n    \n    def __getitem__(self, idx):\n        input_ids = self.input_ids[idx]\n        return {"input_ids": input_ids, "labels": input_ids.clone()}\n\n# --- Setup ---\nmodel_name = "Qwen/Qwen2.5-0.5B"\ntokenizer = AutoTokenizer.from_pretrained(model_name, trust_remote_code=True)\nmodel = AutoModelForCausalLM.from_pretrained(model_name, trust_remote_code=True)\nmodel = model.cuda()\n\ndataset = SimpleTextDataset(tokenizer)\nloader = DataLoader(dataset, batch_size=4, shuffle=True, num_workers=4, pin_memory=True)\n\noptimizer = torch.optim.AdamW(model.parameters(), lr=1e-4)\n\n# --- Training Loop ---\nmodel.train()\nfor epoch in range(3):\n    for batch in loader:\n        input_ids = batch["input_ids"].cuda()\n        labels = batch["labels"].cuda()\n\n        outputs = model(input_ids=input_ids, labels=labels)\n        loss = outputs.loss\n\n        optimizer.zero_grad()\n        loss.backward()\n        optimizer.step()\n    \n    print(f"Epoch {epoch} complete")\n'})}),"\n",(0,s.jsx)(n.h2,{id:"step-2-initialize-the-process-group",children:"Step 2: Initialize the Process Group"}),"\n",(0,s.jsxs)(n.p,{children:["The process group is how PyTorch discovers all participating GPUs. We use ",(0,s.jsx)(n.code,{children:"torchrun"})," to launch, which sets environment variables (",(0,s.jsx)(n.code,{children:"RANK"}),", ",(0,s.jsx)(n.code,{children:"WORLD_SIZE"}),", ",(0,s.jsx)(n.code,{children:"LOCAL_RANK"}),", ",(0,s.jsx)(n.code,{children:"MASTER_ADDR"}),", ",(0,s.jsx)(n.code,{children:"MASTER_PORT"}),") automatically."]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-python",children:'import os\nimport torch\nimport torch.distributed as dist\nfrom datetime import timedelta\n\ndef setup_distributed():\n    """Initialize the distributed process group."""\n    dist.init_process_group(\n        backend="nccl",\n        timeout=timedelta(minutes=30),  # Increase from 10-min default for large clusters\n    )\n    \n    rank = int(os.environ["RANK"])\n    local_rank = int(os.environ["LOCAL_RANK"])\n    world_size = int(os.environ["WORLD_SIZE"])\n    \n    torch.cuda.set_device(local_rank)\n    \n    # Reproducibility (we\'ll use rank-dependent seeding in the full script \u2014 Step 5)\n    torch.manual_seed(42)\n    torch.cuda.manual_seed_all(42)\n    \n    return rank, local_rank, world_size\n\ndef cleanup():\n    """Destroy the process group."""\n    dist.destroy_process_group()\n'})}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"NCCL Timeout:"})," The default NCCL timeout is 10 minutes (PyTorch 2.x). For large clusters (32+ nodes) or when debugging, increase it. If a rank hangs longer than the timeout, PyTorch raises an error instead of hanging indefinitely."]}),"\n"]}),"\n",(0,s.jsx)(n.h2,{id:"step-3-wrap-the-model-with-ddp",children:"Step 3: Wrap the Model with DDP"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-python",children:"from torch.nn.parallel import DistributedDataParallel as DDP\n\n# After model is on the correct GPU:\nmodel = model.to(local_rank)\nmodel = DDP(model, device_ids=[local_rank])\n"})}),"\n",(0,s.jsxs)(n.p,{children:["After wrapping, ",(0,s.jsx)(n.code,{children:"model.forward()"})," works the same as before. DDP hooks into ",(0,s.jsx)(n.code,{children:".backward()"})," to fire AllReduce on gradients transparently."]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Tip:"})," Access the underlying model with ",(0,s.jsx)(n.code,{children:"model.module"})," (e.g., for saving checkpoints)."]}),"\n"]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsxs)(n.strong,{children:[(0,s.jsx)(n.code,{children:"find_unused_parameters"}),":"]})," If your model has conditionally unused parameters (common with some HuggingFace models that have optional heads), DDP will hang silently waiting for gradients that never arrive. Fix: ",(0,s.jsx)(n.code,{children:"DDP(model, device_ids=[local_rank], find_unused_parameters=True)"}),". Only enable this if needed \u2014 it adds overhead."]}),"\n"]}),"\n",(0,s.jsx)(n.h2,{id:"step-4-use-distributedsampler-for-data",children:"Step 4: Use DistributedSampler for Data"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-python",children:"from torch.utils.data import DataLoader, DistributedSampler\n\nsampler = DistributedSampler(dataset, num_replicas=world_size, rank=rank, shuffle=True)\n\nloader = DataLoader(\n    dataset,\n    batch_size=4,\n    sampler=sampler,\n    num_workers=4,\n    pin_memory=True,\n    drop_last=True,\n    persistent_workers=True,\n)\n\n# In the training loop, set the epoch for proper shuffling:\nfor epoch in range(num_epochs):\n    sampler.set_epoch(epoch)  # <-- critical for shuffling\n    for batch in loader:\n        ...\n"})}),"\n",(0,s.jsx)(n.h2,{id:"learning-rate-scaling",children:"Learning Rate Scaling"}),"\n",(0,s.jsxs)(n.p,{children:["When you go from 1 GPU to N GPUs, your effective batch size increases N\xd7. The ",(0,s.jsx)(n.strong,{children:"linear scaling rule"})," adjusts the learning rate accordingly:"]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-python",children:"base_lr = 1e-4            # LR you'd use on a single GPU\nscaled_lr = base_lr * world_size  # Linear scaling\n\n# Alternative: square root scaling (more conservative, often works better)\nscaled_lr = base_lr * (world_size ** 0.5)\n"})}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Rule of thumb:"})," Start with linear scaling. If training is unstable, try square root scaling or reduce the LR manually."]}),"\n"]}),"\n",(0,s.jsx)(n.h2,{id:"step-5-full-working-script",children:"Step 5: Full Working Script"}),"\n",(0,s.jsxs)(n.p,{children:["Save this as ",(0,s.jsx)(n.code,{children:"train_ddp.py"}),":"]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-python",children:'#!/usr/bin/env python3\n"""\nPyTorch DDP pre-training script using Qwen2.5-0.5B.\nLaunch with: torchrun --nproc_per_node=NUM_GPUS train_ddp.py\n"""\n\nimport os\nimport signal\nfrom contextlib import nullcontext\nimport torch\nimport torch.distributed as dist\nfrom datetime import timedelta\nfrom torch.nn.parallel import DistributedDataParallel as DDP\nfrom torch.utils.data import DataLoader, Dataset, DistributedSampler\nfrom transformers import AutoModelForCausalLM, AutoTokenizer\n\n\n# \u2500\u2500\u2500 Configuration \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nBATCH_SIZE_PER_GPU = 4\nACCUMULATION_STEPS = 2\nNUM_EPOCHS = 3\nBASE_LR = 1e-4\nMAX_GRAD_NORM = 1.0          # Gradient clipping\nCHECKPOINT_DIR = "/fsx/checkpoints/qwen-ddp"\nCHECKPOINT_INTERVAL = 500    # Steps between checkpoints\nMODEL_NAME = "Qwen/Qwen2.5-0.5B"\n\n\n# \u2500\u2500\u2500 Dataset \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nclass SimpleTextDataset(Dataset):\n    """Random token sequences for demonstration purposes."""\n    def __init__(self, vocab_size: int, num_samples: int = 10000, seq_length: int = 512):\n        self.input_ids = torch.randint(0, vocab_size, (num_samples, seq_length))\n    \n    def __len__(self):\n        return len(self.input_ids)\n    \n    def __getitem__(self, idx):\n        input_ids = self.input_ids[idx]\n        return {"input_ids": input_ids, "labels": input_ids.clone()}\n\n\n# \u2500\u2500\u2500 Distributed Setup \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ndef setup():\n    dist.init_process_group(\n        backend="nccl",\n        timeout=timedelta(minutes=30),  # Default is 10 min; increase for large clusters\n    )\n    rank = int(os.environ["RANK"])\n    local_rank = int(os.environ["LOCAL_RANK"])\n    world_size = int(os.environ["WORLD_SIZE"])\n    torch.cuda.set_device(local_rank)\n    \n    # Reproducibility\n    torch.manual_seed(42 + rank)\n    torch.cuda.manual_seed_all(42 + rank)\n    \n    return rank, local_rank, world_size\n\n\ndef cleanup():\n    dist.destroy_process_group()\n\n\n# \u2500\u2500\u2500 Checkpointing \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ndef save_checkpoint(model, optimizer, epoch, step, loss, checkpoint_dir):\n    """Save model + optimizer state. Only rank 0 writes."""\n    dist.barrier()\n    rank = int(os.environ["RANK"])\n    \n    if rank == 0:\n        os.makedirs(checkpoint_dir, exist_ok=True)\n        checkpoint = {\n            "epoch": epoch,\n            "step": step,\n            "model_state_dict": model.module.state_dict(),\n            "optimizer_state_dict": optimizer.state_dict(),\n            "loss": loss,\n        }\n        tmp_path = os.path.join(checkpoint_dir, "checkpoint_tmp.pt")\n        final_path = os.path.join(checkpoint_dir, f"checkpoint_epoch{epoch}_step{step}.pt")\n        latest_path = os.path.join(checkpoint_dir, "checkpoint_latest.pt")\n        \n        torch.save(checkpoint, tmp_path)\n        os.rename(tmp_path, final_path)\n        \n        if os.path.islink(latest_path) or os.path.exists(latest_path):\n            os.remove(latest_path)\n        os.symlink(final_path, latest_path)\n        print(f"[Rank 0] Checkpoint saved: {final_path}")\n    \n    dist.barrier()\n\n\ndef load_checkpoint(model, optimizer, checkpoint_dir):\n    """Load checkpoint on all ranks. Returns (epoch, step) to resume from."""\n    latest_path = os.path.join(checkpoint_dir, "checkpoint_latest.pt")\n    \n    if not os.path.exists(latest_path):\n        return 0, 0\n    \n    local_rank = int(os.environ["LOCAL_RANK"])\n    checkpoint = torch.load(latest_path, map_location=f"cuda:{local_rank}", weights_only=False)\n    \n    model.module.load_state_dict(checkpoint["model_state_dict"])\n    optimizer.load_state_dict(checkpoint["optimizer_state_dict"])\n    \n    rank = int(os.environ["RANK"])\n    if rank == 0:\n        print(f"[Rank 0] Resumed from epoch {checkpoint[\'epoch\']}, step {checkpoint[\'step\']}")\n    \n    dist.barrier()\n    return checkpoint["epoch"], checkpoint["step"]\n\n\n# \u2500\u2500\u2500 Main \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ndef main():\n    rank, local_rank, world_size = setup()\n    \n    # \u2500\u2500\u2500 SIGTERM handler for graceful preemption (HyperPod) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    should_stop = False\n    def sigterm_handler(signum, frame):\n        nonlocal should_stop\n        should_stop = True\n        if rank == 0:\n            print("[Rank 0] SIGTERM received \u2014 saving checkpoint and exiting gracefully.")\n    signal.signal(signal.SIGTERM, sigterm_handler)\n    \n    def log(msg):\n        if rank == 0:\n            print(msg)\n    \n    # \u2500\u2500\u2500 Effective batch size \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    effective_batch_size = BATCH_SIZE_PER_GPU * world_size * ACCUMULATION_STEPS\n    scaled_lr = BASE_LR * world_size  # Linear scaling rule\n    \n    log(f"DDP initialized: world_size={world_size}")\n    log(f"Effective batch size: {BATCH_SIZE_PER_GPU} \xd7 {world_size} \xd7 {ACCUMULATION_STEPS} = {effective_batch_size}")\n    log(f"Learning rate: {BASE_LR} \xd7 {world_size} = {scaled_lr}")\n    \n    # \u2500\u2500\u2500 Model \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    log(f"Loading model: {MODEL_NAME}")\n    \n    tokenizer = AutoTokenizer.from_pretrained(MODEL_NAME, trust_remote_code=True)\n    model = AutoModelForCausalLM.from_pretrained(\n        MODEL_NAME,\n        trust_remote_code=True,\n        torch_dtype=torch.bfloat16,\n    )\n    model = model.to(local_rank)\n    model = DDP(model, device_ids=[local_rank])\n    \n    # \u2500\u2500\u2500 Data \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    dataset = SimpleTextDataset(\n        vocab_size=tokenizer.vocab_size,\n        num_samples=10000,\n        seq_length=512,\n    )\n    \n    sampler = DistributedSampler(\n        dataset, num_replicas=world_size, rank=rank, shuffle=True\n    )\n    \n    loader = DataLoader(\n        dataset,\n        batch_size=BATCH_SIZE_PER_GPU,\n        sampler=sampler,\n        num_workers=4,\n        pin_memory=True,\n        drop_last=True,\n        persistent_workers=True,\n    )\n    \n    # \u2500\u2500\u2500 Optimizer \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    optimizer = torch.optim.AdamW(model.parameters(), lr=scaled_lr, weight_decay=0.01)\n    \n    # \u2500\u2500\u2500 Resume from checkpoint \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    start_epoch, start_step = load_checkpoint(model, optimizer, CHECKPOINT_DIR)\n    \n    # \u2500\u2500\u2500 Training Loop \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    model.train()\n    \n    for epoch in range(start_epoch, NUM_EPOCHS):\n        sampler.set_epoch(epoch)\n        total_loss = 0.0\n        num_steps = 0\n        optim_step = 0\n        \n        for step, batch in enumerate(loader):\n            # Skip steps already completed when resuming\n            # Note: DataLoader still fetches skipped batches \u2014 acceptable for this\n            # demo dataset. Production: use DataLoader state_dict (PyTorch 2.4+).\n            if epoch == start_epoch and step <= start_step and start_step > 0:\n                continue\n            \n            # Check for preemption signal\n            if should_stop:\n                save_checkpoint(model, optimizer, epoch, step, total_loss / max(num_steps, 1), CHECKPOINT_DIR)\n                cleanup()\n                return\n            \n            input_ids = batch["input_ids"].to(local_rank)\n            labels = batch["labels"].to(local_rank)\n            \n            # \u2500\u2500\u2500 Gradient accumulation with no_sync \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n            # DDP fires AllReduce on every .backward(). For accumulation,\n            # skip the sync on intermediate steps to avoid wasted communication.\n            is_accumulation_step = (step + 1) % ACCUMULATION_STEPS != 0\n            context = model.no_sync() if is_accumulation_step else nullcontext()\n            \n            with context:\n                outputs = model(input_ids=input_ids, labels=labels)\n                loss = outputs.loss / ACCUMULATION_STEPS\n                loss.backward()\n            \n            total_loss += loss.item() * ACCUMULATION_STEPS\n            num_steps += 1\n            \n            if not is_accumulation_step:\n                # Gradient clipping (essential for stable pre-training)\n                torch.nn.utils.clip_grad_norm_(model.parameters(), MAX_GRAD_NORM)\n                optimizer.step()\n                optimizer.zero_grad()\n                optim_step += 1\n                \n                # \u2500\u2500\u2500 Logging with proper metric aggregation \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n                if optim_step % 50 == 0:\n                    # Aggregate loss across all ranks for accurate global metric\n                    loss_tensor = torch.tensor([loss.item() * ACCUMULATION_STEPS], device=local_rank)\n                    dist.all_reduce(loss_tensor, op=dist.ReduceOp.AVG)\n                    log(f"  Epoch {epoch} | Optim step {optim_step} | Global Avg Loss: {loss_tensor.item():.4f}")\n            \n            # \u2500\u2500\u2500 Periodic checkpoint \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n            global_step = epoch * len(loader) + step\n            if global_step > 0 and global_step % CHECKPOINT_INTERVAL == 0:\n                save_checkpoint(model, optimizer, epoch, step, loss.item(), CHECKPOINT_DIR)\n        \n        # Epoch-end aggregated loss\n        epoch_loss = torch.tensor([total_loss / max(num_steps, 1)], device=local_rank)\n        dist.all_reduce(epoch_loss, op=dist.ReduceOp.AVG)\n        log(f"Epoch {epoch} complete | Global Avg Loss: {epoch_loss.item():.4f}")\n    \n    # \u2500\u2500\u2500 Final checkpoint \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    save_checkpoint(model, optimizer, NUM_EPOCHS - 1, step, epoch_loss.item(), CHECKPOINT_DIR)\n    cleanup()\n\n\nif __name__ == "__main__":\n    main()\n'})}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"To test locally on a single node with 4 GPUs:"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-bash",children:"torchrun --nproc_per_node=4 train_ddp.py\n"})})]})}function p(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},8453(e,n,t){t.d(n,{R:()=>o,x:()=>a});var i=t(6540);const s={},r=i.createContext(s);function o(e){const n=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),i.createElement(r.Provider,{value:n},e.children)}}}]);